class Solution {
  private static long[] dijkstra(int n, List<long[]>[] adj, int src) {
    long[] dist = new long[n];
    java.util.Arrays.fill(dist, Long.MAX_VALUE);
    dist[src] = 0;
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    pq.add(new long[] {0, src});
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int u = (int) top[1];
      if (top[0] > dist[u]) continue;
      for (long[] e : adj[u]) {
        int v = (int) e[0];
        if (top[0] + e[1] < dist[v]) {
          dist[v] = top[0] + e[1];
          pq.add(new long[] {dist[v], v});
        }
      }
    }
    return dist;
  }

  @SuppressWarnings("unchecked")
  public int[] minCost(int n, int[] prices, int[][] roads) {
    List<long[]>[] empty = new List[n], taxed = new List[n];
    for (int i = 0; i < n; i++) {
      empty[i] = new ArrayList<>();
      taxed[i] = new ArrayList<>();
    }
    for (int[] r : roads) {
      empty[r[0]].add(new long[] {r[1], r[2]});
      empty[r[1]].add(new long[] {r[0], r[2]});
      taxed[r[0]].add(new long[] {r[1], (long) r[2] * r[3]});
      taxed[r[1]].add(new long[] {r[0], (long) r[2] * r[3]});
    }
    int[] ans = new int[n];
    for (int i = 0; i < n; i++) {
      long[] de = dijkstra(n, empty, i), dt = dijkstra(n, taxed, i);
      long best = prices[i];
      for (int j = 0; j < n; j++) {
        if (de[j] == Long.MAX_VALUE || dt[j] == Long.MAX_VALUE) continue;
        best = Math.min(best, de[j] + prices[j] + dt[j]);
      }
      ans[i] = (int) best;
    }
    return ans;
  }
}
